* Run transient analysis for 2 us (20 clock cycles)
tran 0.2n 2000n uic

* Output common-mode voltages (ideally VCM = 0.5V)
let v_out_cm = (v(voutp) + v(voutm)) / 2
let v_op_cm = (v(vop) + v(vom)) / 2
meas tran vocm_avg avg v_out_cm from=1000n to=2000n

* Diff-amp output common-mode voltage (ideally Vbias1)
let v_diff_cm = (v(vopd) + v(vomd)) / 2
meas tran vdiff_ocm_avg avg v_diff_cm from=1000n to=2000n

* Diff-amp tail node voltage
meas tran vtail_avg avg v(n014) from=1000n to=2000n

* Differential output amplitude
let v_diff_out = v(voutp) - v(voutm)
meas tran vout_diff_max max v_diff_out from=1000n to=2000n
meas tran vout_diff_min min v_diff_out from=1000n to=2000n
let vout_pp = vout_diff_max - vout_diff_min
print vout_pp

* Settling time in hold cycle (phi2 high around 1.75 us)
meas tran t_phi2_rise when v(phi2)=0.9 rise=18
meas tran vdiff_target find v_diff_out at=1790n
meas tran t_settled when v_diff_out=vdiff_target cross=1
let t_settling = 1790n - t_phi2_rise
print t_settling

* Power consumption
let power = -i(vdd) * 1.8
meas tran avg_power avg power from=1000n to=2000n
print avg_power

quit
.endc
.end

